      "console.routing.components.strategytab.text.uuzjnp": "Load balancing and distribution strategy",
      "console.routing.components.strategytab.text.twpg4h": "Globally defines how model request dispatch is distributed to multiple channel endpoints in the backend.",
      "console.routing.components.strategytab.text.xuhjce": "Lowest Latency",
      "console.routing.components.strategytab.text.x4iuwl": "The system continuously tests the speed in the background and prioritizes allocating requests to the node with the fastest response in the last minute.",
      "console.routing.components.strategytab.text.mmkke0": "Weighted Round Robin",
      "console.routing.components.strategytab.text.1wmtpij": "According to the Weight parameter in the channel configuration, traffic is allocated in proportional polling. Suitable for mixing expensive and low-priced interfaces.",
      "console.routing.components.strategytab.text.9rxhn7": "Cost Optimized",
      "console.routing.components.strategytab.text.ca0sc9": "Try to use the lowest cost channel available and only switch to expensive channels in case of failure.",
      "console.routing.components.strategytab.text.swyut0": "Model Remap",
      "console.routing.components.strategytab.text.ueniy9": "After enabling load balancing, it is recommended to enable",
      "console.routing.components.strategytab.text.1qvfyx6": "Unified model mapping",
      "console.routing.components.strategytab.text.12efdt8": "feature. For example, clients can request",
