      "console.settings.settingsview.text.nvk1uw": "Monthly bill reminder",
      "console.settings.settingsview.text.13ohdai": "At the beginning of each month, after the system completes and generates the concurrent call list and deduction statistics for all multi-modal large models in the previous month, it will send you a detailed email reminder.",
