      "productDocs.title": "产品文档",
      "productDocs.subtitle": "全面了解 Claw Router 的功能、架构和能力。",
      "productDocs.overview": "产品概述",
      "productDocs.overviewDesc": "Claw Router 是一个企业级 AI 聚合平台，旨在简化基础模型的集成、管理和扩展。通过提供统一的 API，它消除了供应商锁定，并降低了构建多模态 AI 应用程序的复杂性。",
      "productDocs.coreFeatures": "核心功能",
      "productDocs.coreFeaturesDesc": "探索使 Claw Router 成为 AI 基础设施终极选择的强大功能。",
      "productDocs.f1Title": "统一多模态 API",
      "productDocs.f1Desc": "通过单一、标准化的 REST API 访问 LLM、图像生成、视频创建和音频处理模型。无需重写代码即可即时切换供应商。",
      "productDocs.f2Title": "智能路由",
      "productDocs.f2Desc": "根据成本、延迟或可用性自动路由请求。实施回退策略，以确保关键应用程序的最长正常运行时间。",
      "productDocs.f3Title": "集中计费与分析",
      "productDocs.f3Desc": "在一个地方管理所有 AI 支出。深入了解不同模型和项目的 Token 使用情况、延迟和成本。",
      "productDocs.architecture": "架构设计",
      "productDocs.architectureDesc": "专为高可用性和低延迟而构建，我们全球分布的边缘网络可确保您的请求得到快速、安全的处理。",
      "productDocs.useCases": "应用场景",
      "productDocs.useCasesDesc": "了解行业领导者如何利用 Claw Router 构建下一代应用程序。",
      "productDocs.uc1Title": "企业 AI 助手",
      "productDocs.uc1Desc": "构建强大的内部工具，在用于复杂推理的高智能模型和用于简单任务的更快、更便宜的模型之间无缝切换。",
      "productDocs.uc2Title": "内容生成平台",
      "productDocs.uc2Desc": "创建多模态内容管道，结合文本生成、图像合成和画外音，为每个特定任务使用最佳模型。",
      "productDocs.security": "安全与合规",
      "productDocs.securityDesc": "安全内置于 Claw Router 的核心。我们提供 SOC2 合规性、端到端加密和严格的零数据保留策略，以保护您的敏感信息。",
      "docs.title": "开发文档",
      "docs.subtitle": "了解如何将 Claw Router 集成到您的应用程序中。",
